(() => Array.from(document.querySelectorAll('a[href]')).map(a => {
  const card = a.closest('[class*="model"],article,li,tr,div') || a;
  const text = (card.innerText || a.innerText || '').trim();
  return {title: (a.innerText || text.split('\n')[0] || '').trim().slice(0, 200),
          snippet: text.slice(0, 400), url: a.href || ''};
}).filter(x => x.title && /model|模型/i.test(x.snippet + ' ' + x.url)).slice(0, 40))()

(async () => {
  const names = (Array.isArray(args.names) ? args.names : [])
    .map(n => String(n || '').trim()).filter(Boolean).slice(0, 64);
  const qs = names.map(n => 'names=' + encodeURIComponent(n)).join('&');
  const resp = await fetch(
    '/api/friday/ml/v1/model/type/information/compareModels?' + qs,
    {credentials: 'same-origin', headers: {accept: 'application/json'}});
  const reader = resp.body?.getReader();
  if (!reader) return {ok: false, status: resp.status};
  const decoder = new TextDecoder();
  let text = '', bytes = 0;
  try {
    while (true) {
      const chunk = await reader.read();
      if (chunk.done) break;
      bytes += chunk.value.byteLength;
      if (bytes > 262144) return {ok: false, status: resp.status, reason: 'response_budget'};
      text += decoder.decode(chunk.value, {stream: true});
    }
  } finally { await reader.cancel().catch(() => {}); }
  let body;
  try { body = JSON.parse(text + decoder.decode()); } catch (_) { return {ok: false, status: resp.status}; }
  if (!resp.ok || !body || ![undefined, 0, 200, '0', '200'].includes(body.code) || !Array.isArray(body.data)) {
    return {ok: false, status: resp.status, reason: 'application_error'};
  }
  return {ok: true, code: body.code, data: body.data.slice(0, 64),
          truncated: body.data.length > 64};
})()
